import React, { useState, useEffect, useRef } from "react";
import { useSelector, useDispatch } from "react-redux";
import { Button } from "primereact/button";
import { fetchElementsByIds } from "../../features/cms/cmsSlice";
import { getSectionTextContrastClass } from "../../utils/sectionContrast";
import { getImage, errorImage } from "../../utils/getImage";

const ids = {
  heroImage: "2000000040",
  brandBadge: "2000000041",
  headlineMain: "2000000042",
  headlineSub: "2000000043",
  description: "2000000044",
  statBadges: "2000000045",
  ctaButton: "2000000046",
};

const DEFAULT_STAT_CARDS = [
  { field1: "100%", fieldType1: "Text", fieldId1: "3000000031", field2: "Responsive", fieldType2: "Text", fieldId2: "3000000032" },
  { field1: "0ms", fieldType1: "Text", fieldId1: "3000000033", field2: "Latency", fieldType2: "Text", fieldId2: "3000000034" },
  { field1: "React 18", fieldType1: "Text", fieldId1: "3000000035", field2: "Production Ready", fieldType2: "Text", fieldId2: "3000000036" }
];

const CustomSection = ({ pageName = "Home" }) => {
  const dispatch = useDispatch();
  const data = useSelector((state) => state.cms?.allSections?.[pageName]);
  const cssData = useSelector((state) => state.cms?.allSectionsCss?.[pageName]);
  const contrastClass = getSectionTextContrastClass("dark");

  useEffect(() => {
    dispatch(fetchElementsByIds({
      elementIds: [
        ids.heroImage, ids.brandBadge, ids.headlineMain, ids.headlineSub,
        ids.description, ids.statBadges, ids.ctaButton,
        "3000000031", "3000000032", "3000000033",
        "3000000034", "3000000035", "3000000036",
      ],
      pageName,
    }));
  }, [dispatch, pageName]);

  useEffect(() => {
    Object.values(ids).forEach(id => {
      if (id && cssData?.[id]) {
        const el = document.getElementById(id);
        if (el) el.style.cssText = cssData[id];
      }
    });
    DEFAULT_STAT_CARDS.forEach(card => {
      [card.fieldId1, card.fieldId2].forEach(fid => {
        if (cssData?.[fid]) {
          const el = document.getElementById(fid);
          if (el) el.style.cssText = cssData[fid];
        }
      });
    });
  }, [cssData]);

  const statBadgesArr = Array.isArray(data?.[ids.statBadges]) && data[ids.statBadges].length > 0
    ? data[ids.statBadges]
    : DEFAULT_STAT_CARDS;

