    <section
      id={pageName}
      className={`w-full overflow-x-hidden relative ${contrastClass}`}
      style={{ backgroundColor: "#030712" }}
    >
      <div className="px-3 sm:px-8 lg:px-16 py-6 sm:py-8 lg:py-12 max-w-[1920px] mx-auto">
        <div className="flex flex-col lg:flex-row items-center gap-8 lg:gap-16">
          <div className="w-full lg:w-1/2 flex justify-center order-1 lg:order-1">
            <img
              id={ids.heroImage}
              className="dynamicStyle2 max-w-full max-h-[600px] h-auto object-cover rounded-2xl shadow-2xl"
              src={data?.[ids.heroImage] ? getImage(data[ids.heroImage]) : getImage("https://images.unsplash.com/photo-1551434678-e076c223a692?auto=format&fit=crop&w=1200&q=80")}
              onError={errorImage}
              alt="AI Studio visual representation"
            />
          </div>

          <div className="w-full lg:w-1/2 flex flex-col items-center lg:items-start text-center lg:text-left order-2 lg:order-2 space-y-6">
            <span
              id={ids.brandBadge}
